+          }
+        },
+        phone: {
+          input: document.querySelector("#phone"),
+          error: document.querySelector("#phone-error"),
+          validate(value) {
+            const trimmedValue = value.trim();
+
+            if (!trimmedValue) {
+              return "";
+            }
+
+            return /^\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}$/.test(trimmedValue)
+              ? ""
+              : "Error: Enter a 10-digit phone number, such as 555-123-4567.";
+          }
