         --danger-bg: #fff4f2;
         --success: #176b3a;
         --success-bg: #edfdf3;
         --focus: #ffbf47;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       }

       * {
         box-sizing: border-box;
       }

       body {
         min-height: 100vh;
         margin: 0;
         background:
           radial-gradient(circle at top left, rgba(36, 88, 219, 0.18), transparent 32rem),
           linear-gradient(135deg, #f8fbff 0%, var(--bg) 100%);
         color: var(--text);
         line-height: 1.5;
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         z-index: 10;
         transform: translateY(-150%);
         border-radius: 999px;
         background: var(--text);
         color: #ffffff;
         padding: 0.75rem 1rem;
         text-decoration: none;
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       main {
         display: grid;
         min-height: 100vh;
         place-items: center;
         padding: 2rem 1rem;
       }

       .support-card {
         width: min(100%, 42rem);
         border: 1px solid rgba(200, 209, 223, 0.75);
         border-radius: 1.5rem;
         background: rgba(255, 255, 255, 0.94);
         box-shadow: 0 1.5rem 4rem rgba(23, 32, 51, 0.12);
         padding: clamp(1.5rem, 4vw, 3rem);
       }

       .eyebrow {
         margin: 0 0 0.5rem;
         color: var(--accent);
         font-size: 0.875rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 5vw, 3rem);
         line-height: 1.1;
       }

       .intro {
         margin: 1rem 0 2rem;
         color: var(--muted);
         font-size: 1.0625rem;
       }

       .required-note {
         margin: 0 0 1.25rem;
         color: var(--muted);
         font-size: 0.95rem;
       }

       form {
         display: grid;
         gap: 1.25rem;
       }

       .form-field {
         display: grid;
         gap: 0.45rem;
       }

       label {
         font-weight: 700;
       }

       .required-marker {
         color: var(--danger);
         font-weight: 800;
       }

       input {
         width: 100%;
         border: 1px solid var(--border);
         border-radius: 0.9rem;
         background: #ffffff;
         color: var(--text);
         font: inherit;
         padding: 0.9rem 1rem;
         transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
       }

       input:hover {
         border-color: #8ea0ba;
       }

       input:focus {
         border-color: var(--accent);
         box-shadow: 0 0 0 4px rgba(36, 88, 219, 0.18);
         outline: 3px solid transparent;
       }

       input[aria-invalid="true"] {
         border-color: var(--danger);
         background: var(--danger-bg);
       }

       .helper-text,
       .error-message {
         margin: 0;
         font-size: 0.925rem;
       }

       .helper-text {
         color: var(--muted);
       }

       .error-message {
         color: var(--danger);
         font-weight: 700;
       }

       .status-message {
         margin: 0;
         border-radius: 0.9rem;
         padding: 0.9rem 1rem;
         font-weight: 700;
       }

       .status-message:empty {
         display: none;
       }

       .status-message.success {
         border: 1px solid rgba(23, 107, 58, 0.28);
         background: var(--success-bg);
         color: var(--success);
       }

       button {
         min-height: 3rem;
         border: 0;
         border-radius: 999px;
         background: var(--accent);
         color: #ffffff;
         cursor: pointer;
         font: inherit;
         font-weight: 800;
         padding: 0.9rem 1.25rem;
         transition: background-color 160ms ease, transform 160ms ease;
       }

       button:hover {
         background: var(--accent-hover);
         transform: translateY(-1px);
       }

       button:focus {
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

