   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>

     <main id="main-content">
       <section class="support-card" aria-labelledby="support-title">
         <p class="eyebrow">Support</p>
         <h1 id="support-title">Contact our team</h1>
         <p class="intro">Tell us how to reach you and we will connect you with the right support specialist.</p>

         <form id="contact-form" novalidate>
           <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> indicates a required field.</p>

           <div class="form-field">
             <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
             <input
               id="full-name"
               name="full-name"
               type="text"
               autocomplete="name"
               required
               aria-describedby="full-name-error"
             >
             <p class="error-message" id="full-name-error"></p>
           </div>

           <div class="form-field">
             <label for="email">Email address <span class="required-marker" aria-hidden="true">*</span></label>
             <input
               id="email"
               name="email"
               type="email"
               autocomplete="email"
               inputmode="email"
               required
               aria-describedby="email-error"
             >
             <p class="error-message" id="email-error"></p>
           </div>

           <div class="form-field">
             <label for="phone">Phone number (optional)</label>
             <input
               id="phone"
               name="phone"
               type="tel"
               autocomplete="tel"
               inputmode="tel"
               aria-describedby="phone-help phone-error"
             >
             <p class="helper-text" id="phone-help">Expected format: 10 digits, such as 555-123-4567.</p>
             <p class="error-message" id="phone-error"></p>
           </div>

           <p class="status-message" id="form-status" aria-live="polite"></p>

           <button type="submit">Send request</button>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#contact-form");
       const statusMessage = document.querySelector("#form-status");
       const fields = {
         fullName: {
           input: document.querySelector("#full-name"),
           error: document.querySelector("#full-name-error"),
           validate(value) {
             return value.trim() ? "" : "Error: Enter your full name.";
           }
         },
         email: {
           input: document.querySelector("#email"),
           error: document.querySelector("#email-error"),
           validate(value) {
             const trimmedValue = value.trim();

             if (!trimmedValue) {
               return "Error: Enter your email address.";
             }

             return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedValue)
               ? ""
               : "Error: Enter a valid email address, such as name@example.com.";
           }
         },
         phone: {
           input: document.querySelector("#phone"),
           error: document.querySelector("#phone-error"),
           validate(value) {
             const trimmedValue = value.trim();

             if (!trimmedValue) {
               return "";
             }

             return /^\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}$/.test(trimmedValue)
               ? ""
               : "Error: Enter a 10-digit phone number, such as 555-123-4567.";
           }
         }
       };

       function setFieldError(field, message) {
         field.error.textContent = message;

         if (message) {
           field.input.setAttribute("aria-invalid", "true");
           return;
         }

         field.input.removeAttribute("aria-invalid");
       }

       function validateField(field) {
         const message = field.validate(field.input.value);
         setFieldError(field, message);
         return !message;
       }

       Object.values(fields).forEach((field) => {
         field.input.addEventListener("blur", () => validateField(field));
         field.input.addEventListener("input", () => {
           if (field.input.getAttribute("aria-invalid") === "true") {
             validateField(field);
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         statusMessage.textContent = "";
         statusMessage.className = "status-message";

         const invalidFields = Object.values(fields).filter((field) => !validateField(field));
         const firstInvalidField = invalidFields[0];

         if (firstInvalidField) {
           firstInvalidField.input.focus();
           return;
         }

         form.reset();
         Object.values(fields).forEach((field) => setFieldError(field, ""));
         statusMessage.textContent = "Thanks. Your support request is ready to send.";
         statusMessage.classList.add("success");
       });
     </script>
   </body>
 </html>

